```
int main() {
	const unsigned char in_key[16];
	const unsigned char salt[64];
	const unsigned char info[64];
	unsigned char out_key[64];
	size_t out_key_len = sizeof(out_key);
	int ret;

	OSSL_PARAM_BLD *bld = OSSL_PARAM_BLD_new();
	OSSL_PARAM_BLD_push_utf8_string(bld, OSSL_KDF_PARAM_MAC, "KMAC128", 0);
	OSSL_PARAM_BLD_push_size_t(bld, OSSL_KDF_PARAM_MAC_SIZE, 64);
	OSSL_PARAM_BLD_push_octet_string(bld, OSSL_KDF_PARAM_KEY, in_key, 16);
	OSSL_PARAM_BLD_push_octet_string(bld, OSSL_KDF_PARAM_SALT, salt, sizeof(salt));
	OSSL_PARAM_BLD_push_octet_string(bld, OSSL_KDF_PARAM_INFO, info, sizeof(info));
	OSSL_PARAM *params = OSSL_PARAM_BLD_to_param(bld);

	EVP_KDF *kdf = EVP_KDF_fetch(NULL, "SSKDF", NULL);
	if (kdf == NULL) {
		ERR_print_errors_fp(stdout);
		return 1;
	}
	EVP_KDF_CTX *ctx = EVP_KDF_CTX_new(kdf);
	if (ctx == NULL) {
		ERR_print_errors_fp(stdout);
		return 1;
	}
	if ((ret = EVP_KDF_CTX_set_params(ctx, params)) != 1) {
		ERR_print_errors_fp(stdout);
		return 1;
	}
	size_t kdf_size = EVP_KDF_CTX_get_kdf_size(ctx);
	if (kdf_size < SIZE_MAX) {
		out_key_len = kdf_size;
	}
	if ((ret = EVP_KDF_derive(ctx, out_key, out_key_len, NULL)) != 1) {
		ERR_print_errors_fp(stdout);
		return 1;
	}
	printf("Key generation successful!\n");
}
```
I see the issue now is the explicit `EVP_KDF_CTX_get_kdf_size` call. It returns 0 because of the missing digest, which then causes an error in `EVP_KDF_derive`. Perhaps the return value there should be the KMAC output length?

I will fix up the code.. But this logic does not make any sense for a variable length output..
